        if (result == null) {
//      ServletRequest sr = (ServletRequest)pageAttrs.get(REQUEST);
            if (request != null) {
                result = request.getAttribute(name);
            }
        }
        if (result == null) {
//      HttpSession session = (HttpSession)pageAttrs.get(SESSION);
            if (session != null) {
                result = session.getAttribute(name);
            }
        }
        if (result == null) {
//      ServletContext context = (ServletContext)pageAttrs.get(APPLICATION);
            if (application != null) {
                result = application.getAttribute(name);
            }
        }
        return result;
