    public void forward(String relativeUrlPath) throws ServletException, IOException {
//    ServletRequest request = (ServletRequest)pageAttrs.get(REQUEST);
//    ServletResponse response = (ServletResponse)pageAttrs.get(RESPONSE);
        if (request == null) {
            throw new IllegalStateException("Page context not initialized");
        }
        RequestDispatcher dispatcher = request.getRequestDispatcher(relativeUrlPath);
        dispatcher.forward(request, response);
    }

