    public void handlePageException(Exception t) throws ServletException, IOException {
        if (errorPage == null) {
            throw new ServletException(t.getMessage(), t);
        } else {
            request.setAttribute("javax.servlet.jsp.JspException", t);
            if (request.getAttribute("javax.servlet.include.request_uri") == null)
                forward(errorPage);
            else
                include(errorPage);
        }
    }

    public void include(String relativeUrlPath) throws ServletException, IOException {
        if (request == null) {
            throw new IllegalStateException("Page context not initialized");
        }
        RequestDispatcher dispatcher = request.getRequestDispatcher(relativeUrlPath);
        dispatcher.include(request, response);
    }

    public void initialize(Servlet servlet, ServletRequest request, ServletResponse response, String errorPageURL,
                           boolean needsSession, int bufferSize, boolean autoFlush) throws IOException {
// Added by skilz
        if (errorPageURL != null) {
//      pageAttrs.put("errorPage", errorPageURL);
            errorPage = errorPageURL;
        }
//
//    pageAttrs.put(APPLICATION, servlet.getServletConfig().getServletContext());
        page = servlet;
        config = servlet.getServletConfig();
        application = config.getServletContext();
//    pageAttrs.put(CONFIG, servlet.getServletConfig());
        ((NusuthJspWriter) writer).init(bufferSize, autoFlush, response.getOutputStream());
//    pageAttrs.put(OUT, writer);
//    pageAttrs.put(PAGE, servlet);
//    pageAttrs.put(PAGECONTEXT,
//                  new Hashtable());
//    pageContext = new Hashtable();
//    pageAttrs.put(REQUEST, request);
        this.request = request;
//    pageAttrs.put(RESPONSE, response);
        this.response = response;
        if (needsSession) {
//      pageAttrs.put(SESSION, ((HttpServletRequest)request).getSession(true));
            session = ((HttpServletRequest) request).getSession(true);
        }
    }

    public void release() {
//    try {
//      this.getOut().close();
//    } catch (Exception ex) {
//    }
//    writer.cleanUp();
//    pageAttrs.clear();
        application = null;
        config = null;
        page = null;
        request = null;
        response = null;
        session = null;
//    pageContext = null;
        exception = null;
        errorPage = null;
        while (!outs.isEmpty()) {
            writer = (JspWriter) outs.pop();
        }
        ((NusuthJspWriter) writer).cleanUp();
        pageContext.clear();
    }

    public void removeAttribute(String name) {
        removeAttribute(name, PAGE_SCOPE);
    }

    public void removeAttribute(String name, int scope) {
        switch (scope) {
            case PAGE_SCOPE:
//        Hashtable ht = (Hashtable)pageAttrs.get(PAGECONTEXT);
                if (pageContext != null) {
                    pageContext.remove(name);
                }
                break;
            case REQUEST_SCOPE:
//        ServletRequest sr = (ServletRequest)pageAttrs.get(REQUEST);
                if (request != null) {
                    request.removeAttribute(name);
                }
                break;
            case SESSION_SCOPE:
//        HttpSession session = (HttpSession)pageAttrs.get(SESSION);
                if (session != null) {
                    session.removeAttribute(name);
                }
                break;
            case APPLICATION_SCOPE:
//        ServletContext context = (ServletContext)pageAttrs.get(APPLICATION);
                if (application != null) {
                    application.removeAttribute(name);
                }
                break;
            default:
                throw new IllegalArgumentException("Cannot find corresponding scope");
        }
    }

    public void setAttribute(String name, Object attribute) {
        setAttribute(name, attribute, PAGE_SCOPE);
    }

    public void setAttribute(String name, Object attribute, int scope) {
        switch (scope) {
            case PAGE_SCOPE:
//        Hashtable ht = (Hashtable)pageAttrs.get(PAGECONTEXT);
                if (pageContext != null) {
                    pageContext.put(name, attribute);
                }
                break;
            case REQUEST_SCOPE:
//        ServletRequest sr = (ServletRequest)pageAttrs.get(REQUEST);
                if (request != null) {
                    request.setAttribute(name, attribute);
                }
                break;
            case SESSION_SCOPE:
//        HttpSession session = (HttpSession)pageAttrs.get(SESSION);
                if (session != null) {
                    session.setAttribute(name, attribute);
                }
                break;
            case APPLICATION_SCOPE:
//        ServletContext context = (ServletContext)pageAttrs.get(APPLICATION);
                if (application != null) {
                    application.setAttribute(name, attribute);
                }
                break;
            default:
                throw new IllegalArgumentException("Cannot find corresponding scope");
        }
    }

    public BodyContent pushBody() {
        JspWriter current = getOut();
        outs.push(current);
        BodyContent res = new NusuthBodyContent(current);
//    pageAttrs.put(OUT, res);
        writer = res;
        return res;
    }

    public JspWriter popBody() {
        NusuthBodyContent w = (NusuthBodyContent) this.getOut();
        JspWriter res = null;
        try {
            res = (JspWriter) outs.pop();
        } catch (EmptyStackException ese) {
            throw new RuntimeException("Internal error: JspWriter stack is empty");
        }
//    pageAttrs.put(OUT, res);
        writer = res;
        return res;
    }
